// price-triggered-service.js
import { ethers } from "ethers";

const ALCHEMY_URL = process.env.ALCHEMY_RPC_URL;
const INFURA_URL = process.env.INFURA_RPC_URL;
const FEED_ADDRESS = process.env.PRICE_FEED_ADDRESS; // real Sepolia feed, e.g. ETH/USD
const TRIGGER_CONTRACT = process.env.TRIGGER_CONTRACT_ADDRESS;
const THRESHOLD_USD = 2000;

// Step 1 — resilient provider (Lesson 6)
const provider = new ethers.FallbackProvider([
  { provider: new ethers.JsonRpcProvider(ALCHEMY_URL), priority: 1, weight: 1 },
  { provider: new ethers.JsonRpcProvider(INFURA_URL), priority: 2, weight: 1 },
]);
const wallet = new ethers.Wallet(process.env.PRIVATE_KEY, provider);

const feedAbi = [
  "function latestRoundData() view returns (uint80, int256, uint256, uint256, uint80)",
  "function decimals() view returns (uint8)",
];
const feed = new ethers.Contract(FEED_ADDRESS, feedAbi, provider);
const triggerAbi = ["function onPriceCrossed(uint256 price, bool isAbove)"];
const trigger = new ethers.Contract(TRIGGER_CONTRACT, triggerAbi, wallet);

let cachedDecimals = null;
let wasAbove = null;
let nextNonce = null;
let inFlight = false;

// Step 2 — read the feed, never hardcode decimals
async function getPrice() {
  if (cachedDecimals === null) cachedDecimals = await feed.decimals();
  const [, answer] = await feed.latestRoundData();
  return Number(answer) / 10 ** cachedDecimals;
}

// Step 4 — local nonce tracker, avoids a collision between close crossings
async function getNextNonce() {
  if (nextNonce === null) {
    nextNonce = await provider.getTransactionCount(wallet.address, "pending");
  } else {
    nextNonce += 1;
  }
  return nextNonce;
}

// Step 5 + 6 — real fee estimation, send, wait for the real outcome
async function triggerAction(price, isAbove) {
  if (inFlight) {
    console.warn("Previous trigger still confirming — skipping this tick");
    return;
  }
  inFlight = true;
  try {
    const priceScaled = ethers.parseUnits(price.toFixed(2), 2);
    const feeData = await provider.getFeeData();
    const nonce = await getNextNonce();

    const tx = await trigger.onPriceCrossed(priceScaled, isAbove, {
      nonce,
      maxFeePerGas: feeData.maxFeePerGas,
      maxPriorityFeePerGas: feeData.maxPriorityFeePerGas,
    });
    console.log(`Submitted trigger tx ${tx.hash} (nonce ${nonce})`);

    const receipt = await tx.wait(); // Step 6 — don't assume success early
    console.log(`Confirmed in block ${receipt.blockNumber}, status ${receipt.status}`);
  } catch (err) {
    console.error("Trigger transaction failed:", err.message);
  } finally {
    inFlight = false;
  }
}

// Step 3 — crossing detection, not "is it currently above"
async function checkAndTrigger() {
  const price = await getPrice();
  const isAbove = price > THRESHOLD_USD;

  if (wasAbove !== null && isAbove !== wasAbove) {
    await triggerAction(price, isAbove);
  }
  wasAbove = isAbove;
}

setInterval(() => {
  checkAndTrigger().catch((err) => console.error("Poll failed:", err.message));
}, 60_000);
