// resilient-listener.js
import { ethers } from "ethers";
import fs from "node:fs";
import { provider } from "./provider.js"; // the Chapter 1 FallbackProvider

const PROGRESS_FILE = "./last-block.json";
const CONFIRMATIONS = 5;
const MAX_SEEN_IDS = 5000;
const TOKEN_ADDRESS = process.env.TOKEN_ADDRESS;

const abi = ["event Transfer(address indexed from, address indexed to, uint256 value)"];
const token = new ethers.Contract(TOKEN_ADDRESS, abi, provider);

function loadState(currentBlock) {
  if (!fs.existsSync(PROGRESS_FILE)) {
    return { lastBlock: currentBlock - 1000, seenEventIds: [] };
  }
  return JSON.parse(fs.readFileSync(PROGRESS_FILE, "utf8"));
}
function saveState(state) {
  fs.writeFileSync(PROGRESS_FILE, JSON.stringify(state));
}

// Step 3 — a correct, unique event identity
function eventId(log) {
  return `${log.transactionHash}-${log.index ?? log.logIndex}`;
}

// Step 2 — Lesson 9's block-hash reorg check, applied at the confirmation gate
async function survivedAnyReorg(log) {
  const blockNow = await provider.getBlock(log.blockNumber);
  return blockNow?.hash === log.blockHash;
}

async function handleTransfer(from, to, value, event, state) {
  const log = event.log ?? event;
  const id = eventId(log);
  if (state.seenEventIds.includes(id)) return; // Step 3 — already processed

  const current = await provider.getBlockNumber();
  if (current - log.blockNumber < CONFIRMATIONS) return; // not deep enough yet

  if (!(await survivedAnyReorg(log))) {
    console.warn(`Reorg detected — discarding ${id} at block ${log.blockNumber}`);
    return; // never mark a reorged-out event as seen
  }

  console.log(`Confirmed transfer ${from} -> ${to}: ${value} (block ${log.blockNumber})`);

  state.seenEventIds.push(id);
  if (state.seenEventIds.length > MAX_SEEN_IDS) state.seenEventIds.shift(); // Step 5
  state.lastBlock = log.blockNumber;
  saveState(state);
}

async function main() {
  const currentBlock = await provider.getBlockNumber();
  const state = loadState(currentBlock);

  // Step 4 — backfill and live listener share one handler
  const missed = await token.queryFilter("Transfer", state.lastBlock + 1, currentBlock);
  for (const event of missed) {
    await handleTransfer(...event.args, event, state);
  }

  token.on("Transfer", (from, to, value, event) => handleTransfer(from, to, value, event, state));

  console.log(`Listening from block ${currentBlock}, caught up on ${missed.length} missed events`);
}

main();
