// frontend.js — Step 2 and the Step 6 wallet-event wiring
import { SiweMessage } from "siwe";
import { BrowserProvider } from "ethers";

async function signIn() {
  const provider = new BrowserProvider(window.ethereum);
  const signer = await provider.getSigner();
  const address = await signer.getAddress();

  const { nonce } = await fetch("/auth/nonce").then((r) => r.json());

  const siweMessage = new SiweMessage({
    domain: window.location.host,
    address,
    statement: "Sign in with Ethereum.",
    uri: window.location.origin,
    version: "1",
    chainId: Number((await provider.getNetwork()).chainId),
    nonce,
  });
  const preparedMessage = siweMessage.prepareMessage();
  const signature = await signer.signMessage(preparedMessage);

  const res = await fetch("/auth/login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ message: siweMessage, signature }),
  });
  return res.json();
}

// The case Lesson 23 says gets skipped most often
window.ethereum.on("accountsChanged", async () => {
  await fetch("/auth/logout", { method: "POST" }); // kill the OLD session first
  await signIn(); // then re-authenticate as whichever address is now active
});

window.ethereum.on("disconnect", async () => {
  await fetch("/auth/logout", { method: "POST" });
});
